parents={}
for n in nodes.values():
 for c in n['children']:parents.setdefault(c,[]).append(n['id'])
def role(summary,tasks,source=None,qualified=False):return dict(summary=summary,tasks=tasks,source=source,qualified=qualified)
def enrich(n):
 t=n['title'].lower();src=n['source']; k=n['kind'];id=n['id']
 if id.startswith('dept-'):
  a,b=DEPARTMENTS[id[5:]];return role(a,b,src)
 if id=='root':return role('Explore Telangana’s executive leadership and its separate public institutions.',['Start with the Chief Minister to follow ministers and departments','Explore the Legislature, Judiciary and Information Commission separately','Use district and Secretariat directories to find listed officials'],src)
 if id=='cm':return role('Leads the elected state government and heads the Council of Ministers.',['Sets the government’s overall policy direction and priorities','Coordinates the work of ministers and the departments held by the CM','Heads the Council of Ministers that aids and advises the Governor'],CONSTITUTION)
 if id=='cabinet':return role('Ministers provide political leadership for their allocated subjects.',['Take policy decisions within their assigned responsibilities','Guide departments and review programme delivery','Answer to the Legislature for government business'],CONSTITUTION)
 if id.startswith('minister'):
  if t=='deputy chief minister':return role('A senior minister who assists the Chief Minister and leads the portfolios allocated to the office.',['Provides political leadership for Finance, Planning and Energy as listed','Reviews policy and programmes in those portfolios','Works as part of the Council of Ministers; the title does not make every minister a direct report'],src)
  return role('Provides political leadership for the portfolios listed below.',['Sets priorities and reviews policy in the allocated subjects','Works with departmental secretaries on programmes and implementation','Answers for the portfolio’s work in the Legislature'],CONSTITUTION)
 if id=='cs':return role('The state’s senior administrative officer, coordinating government administration.',['Coordinates work across departments and administrative priorities','Supports implementation of government decisions','Heads the General Administration Department'],GAD)
 if id=='governor':return role('The constitutional head of the state, with functions defined by the Constitution.',['Appoints the Chief Minister and other ministers under constitutional provisions','Performs legislative functions, including consideration of state Bills','Normally acts on ministerial advice, with constitutionally specified exceptions'],CONSTITUTION)
 if id=='cmo':return role('Supports the Chief Minister in official coordination and office work.',['Processes matters and correspondence received by the CM’s office','Supports coordination with departments and other offices','Includes the officials grouped under CMO by the portal directory'],src)
 if id in ['cmdept','departments']:return role('Departments turn policy in their allocated subject areas into government programmes and services.',['A minister provides political direction for an allocated portfolio','Secretariat officers handle policy and government business','Directorates and agencies carry out subject-specific work; directory links are not a complete reporting chart'],GAD)
 if id=='districts' or k=='District directory':return role('A geographic directory of district-level civil and police officials.',['Collectors coordinate district administration and revenue work','Additional Collectors handle allocated administrative responsibilities','Police leadership is listed alongside civil officials, not as subordinate to the Collector'],COLLECTOR)
 if k=='District directory listing':
  if 'police' in t:return role('Leads policing for the district, commissionerate or assigned police unit.',['Maintains public order and coordinates public-safety responses','Supervises crime prevention and investigation within the assigned unit','Manages police operations and personnel within the office’s remit'],POLICE)
  if 'additional' in t:return role('Assists district administration in the subjects allocated to this office.',['Handles revenue or local-body matters according to the assigned charge','Coordinates officials and programmes in that assigned remit','Supports the Collector in district administrative work'],COLLECTOR,True)
  return role('Leads district administration, including revenue administration and coordination of government programmes.',['Coordinates district-level delivery of government programmes','Handles land-revenue and assigned administrative matters','Coordinates departments and public-service work at district level'],COLLECTOR)
 if id=='legislature':return role('The state Legislature debates laws, public spending and government policy.',['The Assembly and Council conduct legislative business','Members raise public issues and scrutinise the government','Presiding officers conduct proceedings in each House'],CONSTITUTION)
 if t=='speaker':return role('Presides over the Legislative Assembly and conducts its proceedings.',['Conducts sittings and maintains order in the House','Applies the House’s rules of procedure','Facilitates legislative business and member participation'],CONSTITUTION)
 if t=='chairman' and '/legislative-council-chairman/' in src:return role('Presides over the Legislative Council.',['Conducts Council sittings and maintains order','Applies the Council’s procedural rules','Facilitates debates and legislative business'],CONSTITUTION)
 if id=='mlas' or k=='MLA listing' or t=='legislative assembly':return role('MLAs represent Assembly constituencies in the state Legislature.',['Debate and vote on state legislation and public spending','Raise constituency issues and question ministers','Participate in legislative committees and scrutiny of government'],CONSTITUTION)
 if id=='mlcs' or k=='MLC listing' or t=='legislative council':return role('MLCs participate in the state’s upper legislative chamber.',['Examine and debate legislation under the Council’s constitutional powers','Raise public issues and question the government','Participate in Council committees and legislative scrutiny'],CONSTITUTION)
 if id=='parliament' or k=='MP listing' or t in ['lok sabha','rajya sabha']:return role('Members represent Telangana in India’s Parliament, which is separate from the state executive.',['Participate in national lawmaking and parliamentary debate','Scrutinise Union government policy, spending and implementation','Raise public and constituency or state concerns in Parliament'],PARLIAMENT)
 if id=='commission' or 'information commissioner' in t:return role('Handles RTI complaints and second appeals involving state public authorities.',['Examines complaints and appeals under the Right to Information Act','Reviews disputes about access to public information','Exercises the remedial and enforcement powers provided by the Act'],RTI)
 if id=='judiciary' or t=='chief justice' or t=='high court judge' or t=='high court judges':return role('The High Court exercises judicial authority independently of the state executive.',['Hears matters within its constitutional and statutory jurisdiction','Protects legal rights and reviews matters brought before it','The Chief Justice also leads the Court’s administration and allocation of judicial work'],CONSTITUTION)
 if 'registrar' in t or t=='high court registrars':return role('Supports the High Court’s administrative and registry functions.',['Coordinates registry or court-administration work in the assigned section','Supports case-processing or institutional administration as allocated','The exact remit depends on the Registrar’s designation and current work allocation'],src,True)
 if id=='advisors' or 'advisor' in t or k=='Advisory role':return role('Provides advice to the government on the subject assigned to the post.',['Offers subject-specific inputs and recommendations','Supports coordination and review when assigned','An advisory title does not itself establish executive control over a department'],src,True)
 if 'secretariat' in t or id=='secretariat':return role('The Secretariat supports policy, government decisions and administrative coordination.',['Prepares and processes government business in allocated subjects','Coordinates departmental proposals and administrative decisions','Lists officials by department; the directory does not specify every reporting relationship'],GAD)
 if 'dgp' in t or 'police' in t:return role('Performs the police leadership or public-safety function described by the designation.',['Coordinates policing and public-safety work within the assigned remit','Supervises operations or specialist responsibilities allocated to the office','The exact jurisdiction and powers depend on the post'],POLICE,True)
 if 'secretary to chief minister' in t or 'osd to chief minister' in t:return role('Supports the Chief Minister’s office in its assigned administrative work.',['Processes assigned official matters and correspondence','Coordinates with departments on matters referred by the CM’s office','Carries out work according to the office’s current allocation of duties'],src,True)
 if 'secretary' in t:return role('Handles policy and administrative business allocated to this Secretariat post.',['Examines proposals and prepares matters for government decisions','Coordinates with departments, agencies and other government offices','Monitors the subjects assigned to this particular post'],GAD,True)
 if 'engineer' in t:return role('Performs engineering management or technical work in the assigned organisation.',['Plans, examines or supervises engineering work within the assigned charge','Supports technical standards, project monitoring and maintenance','Exact approval powers and project responsibilities depend on the designation'],src,True)
 if 'director' in t or 'commissioner' in t:return role('Leads or supports administration and programme delivery in the listed directorate or agency.',['Coordinates the functions assigned to this office','Reviews operational matters and programme progress','Manages proposals, staff or services within the office’s delegated responsibilities'],src,True)
 if 'section officer' in t or 'superintendent' in t:return role('Supervises the assigned office section and the processing of its work.',['Organises files, correspondence and case processing','Checks administrative notes and proposals in the assigned section','Supports decisions by the competent authority'],src,True)
 if 'account' in t or 'finance' in t or 'treasur' in t:return role('Handles the financial or accounts function identified by the post.',['Maintains or reviews financial records within the assigned remit','Processes accounts, payments or financial proposals as allocated','Supports compliance with applicable financial procedures'],src,True)
 if k in ['Organization / directory heading','Directory grouping','Secretariat directory grouping','Membership directory','Administrative directory','Geographic directory','Institution grouping','Institution','Separate institution','Separate statutory institution'] or n['children']:
  return role('Groups the offices or people published for this institution or subject.',['Open a branch to see the officials and roles listed for it','Use each entry’s official source to check the current listing','Inclusion in a directory is not proof of a direct reporting relationship'],src)
 return role('This post is listed in the official directory for the selected organisation.',['Performs the function indicated by the designation within that organisation','The portal does not publish a complete duty statement for this entry','Use the source listing to confirm the office’s current work allocation'],src,True)
for n in nodes.values():n['role']=enrich(n)
# Associate each person with a portrait on an official page, matching names rather than row position.
def norm(s):
 s=re.sub(r'^(sri\.?|smt\.?|shri|dr\.?|ms\.?|hon.?ble)\s*','',s,flags=re.I)
 s=s.split('@')[0];s=re.split(r',\s*(IAS|IPS|IFS|IRAS)',s,flags=re.I)[0]
 return re.sub('[^a-z]','',s.lower())
portraits=json.loads((P/'portrait-sources.json').read_text()) if (P/'portrait-sources.json').exists() else []
profile_ids={'government/governor/':'governor','government/chief-secretary/':'cs','legislature/legislative-council-chairman/':next(n['id'] for n in nodes.values() if n['title']=='Chairman' and '/legislative-council-chairman/' in n['source']),'legislature/legislative-assembly-speaker/':next(n['id'] for n in nodes.values() if n['title']=='Speaker'),'judiciary/chief-justice/':next(n['id'] for n in nodes.values() if n['title']=='Chief Justice')}
for r in portraits:
 if 'path' not in r:continue
 if 'profile' in r:matches=[nodes[profile_ids[r['profile']]]]
 else:matches=[n for n in nodes.values() if norm(n['sub'])==norm(r.get('name','')) or norm(n['title'])==norm(r.get('name',''))]
 for n in matches:n['photo']=r['path'];n['photoSource']=r['source'];n['photoOriginal']=r['image']
# Explicitly describe a general educational overview, not a personal activity claim.
m['roleNote']='Role explanations describe the office in plain English. For specialist or support posts, they are indicative; the current work allocation remains with the relevant authority.'
m['photoCount']=sum(bool(n.get('photo')) for n in nodes.values())
for n in nodes.values():
 if n['kind']=='MLA listing':n['fields'].insert(0,['Constituency',n['title']])
 if n['kind']=='MLC listing':n['fields'].insert(0,['Constituency listed',n['sub']])
 if n['kind']=='MP listing':n['fields'].insert(0,['Party listed',n['sub']])
roles=[]; role_ids={}
for n in nodes.values():
 key=json.dumps(n['role'],sort_keys=True)
 if key not in role_ids:role_ids[key]=len(roles);roles.append(n['role'])
 n['roleId']=role_ids[key];del n['role']
m['roles']=roles
(P/'src/data.json').write_text(json.dumps(m,ensure_ascii=False,separators=(',',':')))
print('Enriched',len(nodes),'nodes;',m['photoCount'],'portrait associations')
